      for (const [k, g] of Object.entries(GAMES.games)) lines.push(`• <code>/games ${k}</code> — ${esc(g.name_fa)}`);
      lines.push("", "<i>دادهٔ سرورها از پروژهٔ MIT «pingdiff».</i>");
